import React, { useState, useEffect, useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { STLLoader } from 'three/examples/jsm/loaders/STLLoader';
import * as THREE from 'three';

// STL Viewer component with wireframe toggle
function STLViewer({ path }) {
  const [geometry, setGeometry] = useState(null);
  const [isWireframe, setIsWireframe] = useState(true); // Toggle wireframe on/off
  const meshRef = useRef();

  // Load the STL model and set the geometry
  useEffect(() => {
    const loader = new STLLoader();
    loader.load(
      path,
      (geometry) => {
        geometry.center(); // Center the model in the scene
        setGeometry(geometry);
      },
      (xhr) => {
        // Optional: Track loading progress
        console.log(`Loading STL: ${(xhr.loaded / xhr.total) * 100}%`);
      },
      (error) => {
        console.error('Error loading STL:', error);
        setGeometry(null); // Display placeholder if the STL fails to load
      }
    );
  }, [path]);

  const handleToggleWireframe = () => {
    setIsWireframe(!isWireframe); // Toggle wireframe mode
  };

  if (!geometry) {
    return <PlaceholderModel error={true} />; // Show placeholder on error
  }

  return (
    <group>
      <mesh ref={meshRef} geometry={geometry}>
        {/* Use wireframe material based on isWireframe state */}
        <meshStandardMaterial
          color="#00ffff" // Color of the model
          wireframe={isWireframe} // Toggle wireframe based on state
        />
      </mesh>
      <button
        style={{
          position: 'absolute',
          top: '20px',
          left: '20px',
          padding: '10px',
          backgroundColor: '#00ffff',
          border: 'none',
          color: '#fff',
          fontSize: '16px',
          cursor: 'pointer',
        }}
        onClick={handleToggleWireframe}
      >
        Toggle Wireframe
      </button>
    </group>
  );
}

// Placeholder Model to show on load error
function PlaceholderModel({ error = false }) {
  const meshRef = useRef();

  // Rotate the placeholder model continuously using useFrame
  useFrame(() => {
    if (meshRef.current) {
      meshRef.current.rotation.x += 0.01;
      meshRef.current.rotation.y += 0.01;
    }
  });

  return (
    <group>
      <mesh ref={meshRef}>
        <boxGeometry args={[2, 2, 2]} />
        <meshStandardMaterial color="gray" wireframe={true} />
      </mesh>
      {error && (
        <textSprite
          text="Error Loading STL"
          color="#ff0000"
          fontSize={0.5}
          position={[0, -3, 0]}
        />
      )}
    </group>
  );
}

export default STLViewer;
